00098 class FileEncoderImpl : public FileEncoder {
00099 public:
00100     //
00101     FileEncoderImpl(const ImageDescription &image_description, unsigned fps, const Parameters &parameters);
00102 
00103     ~FileEncoderImpl() override;
00104 
00105     // Encode from 'src' YUV file, up to 'limit' frames (if limit > 0)
00106     //
00107     void encode_file(const string &src_filename, const string &dst_filename, const string &dst_filename_yuv,
00108                      unsigned limit) override;
00109 
00110     // Encode from 'src' base file which will run the base deocoder first
00111     //
00112     void encode_file_with_decoder(const string &src_filename, const string base_filename, const string &dst_filename,
00113                                   const string &dst_filename_yuv, unsigned limit) override;
00114 
00115     // Encode from 'src' YUV file, base, base_recon & preprocessed info
00116     //
00117     void encode_file_with_base(const string &src_filename, const string base_filename, const string base_recon_filename,
00118                                const string &dst_filename, const string &dst_filename_yuv, unsigned limit) override;
00119 
00120     void downsample_file(const string &src_filename, const string &dst_filename, unsigned limit) override;
00121     void upsample_file(const string &src_filename, const string &dst_filename, unsigned limit) override;
00122 
00123     virtual BaseDecoder::Codec es_file_type() const = 0;
00124     virtual BaseCoding base_coding() const = 0;
00125 
00126 protected:
00127     // Body of encode loop
00128     void encode(const YUVReader &src_file, const YUVReader &recon_file, FILE *output_file, ESFile &es_file,
00129                 const string &dst_filename_yuv, unsigned limit);
00130 
00131     bool read_au(ESFile &es_file, ESFile::AccessUnit &au);
00132     Packet rbsp_encapsulate(const Packet &src) const;
00133 
00134     void initialize_encoder(const YUVReader &src_file, unsigned limit);
00135     struct RegisteredSEI {
00136         static Packet sei_payload(const Packet &enhancement_data);
00137     };
00138     struct UnregisteredSEI {
00139         static Packet sei_payload(const Packet &enhancement_data);
00140     };
00141     Packet nal_payload(const Packet &enhancement_data) const;
00142 
00143     virtual int add_enhancement(ESFile::AccessUnit &au, bool is_idr, const Packet &payload) = 0;
00144 
00145     ESFile::NalUnit build_nalu(bool is_idr, const Packet &payload) const;
00146 
00147     unsigned intra_period() const;
00148 
00149     virtual bool run_base_encoder(const string &input, const string &stream_output, const string &recon_output,
00150                                   unsigned frame_count) const = 0;
00151     virtual bool run_base_decoder(const string &input, const string &output) = 0;
00152 
00153     // Size, format & depth - base, intermediate & full resolution
00154     //
00155     const unsigned fps_;
00156     const Parameters parameters_;
00157 
00158     const ScalingMode scaling_mode_[MAX_NUM_LOQS];
00159     const Downsample downsample_luma_;
00160     const Downsample downsample_chroma_;
00161     const Upsample upsample_;
00162     unsigned upsampling_coefficients_[4];
00163 
00164     const Encapsulation encapsulation_;
00165 
00166     Encoder encoder_;
00167 };
