00169 FileEncoderImpl::FileEncoderImpl(const ImageDescription &image_description, unsigned fps, const Parameters &parameters)
00170     : fps_(fps), parameters_(parameters), scaling_mode_{parameters_["scaling_mode_level1"].get_enum<ScalingMode>(ScalingMode_None),
00171                                                         parameters_["scaling_mode_level2"].get_enum<ScalingMode>(ScalingMode_2D)},
00172       downsample_luma_(parameters_["encoding_downsample_luma"].get_enum<Downsample>(Downsample_Lanczos3)),
00173       downsample_chroma_(parameters_["encoding_downsample_chroma"].get_enum<Downsample>(Downsample_Lanczos3)),
00174       upsample_(parameters_["encoding_upsample"].get_enum<Upsample>(Upsample_ModifiedCubic)),
00175       encapsulation_(parameters_["encapsulation"].get_enum<Encapsulation>(Encapsulation_None)),
00176       encoder_(image_description, parameters) {
00177 
00178     parameters_["encoding_upsample"].get_vector<unsigned>(upsampling_coefficients_, 4);
00179 }
00180 
00181 FileEncoderImpl::~FileEncoderImpl() {}
00182 
00183 //
00184 //
00185 void FileEncoderImpl::encode_file(const string &src_filename, const string &dst_filename, const string &dst_filename_yuv,
00186                                   unsigned limit) {
00187     // Temp. input file to encode
00188     //
00189     string base_yuv_filename = make_temporary_filename("_base.yuv");
00190 
00191     // Output files
00192     //
00193     string base_bin_filename;
00194     string base_recon_filename;
00195 
00196     if (!parameters_["keep_base"].get<bool>(false)) {
00197         base_bin_filename = make_temporary_filename("_base.bin");
00198         base_recon_filename = make_temporary_filename("_base_recon.yuv");
00199     } else {
00200         base_bin_filename = "base.bin";
00201         base_recon_filename = "base_recon.yuv";
00202     }
00203 
00204     INFO("Using temporary file for base YUV: %s", base_yuv_filename.c_str());
00205     INFO("Using temporary file for base stream: %s", base_bin_filename.c_str());
00206     INFO("Using temporary file for base recon: %s", base_recon_filename.c_str());
00207 
00208     // Read source and downsample into base
00209     //
00210     unique_ptr<YUVReader> src_file(CHECK(CreateYUVReader(src_filename, encoder_.src_image_description(), fps_)));
00211     initialize_encoder(*src_file, limit);
00212     auto base_yuv = CHECK(CreateYUVWriter(base_yuv_filename, encoder_.base_image_description(), true));
00213 
00214     int64_t pts = 0;
00215     int64_t duration = 90000L / fps_;
00216 
00217     const unsigned frame_count = min(src_file->length(), limit);
00218     INFO("input limit %8d - local count %8d", limit, frame_count);
00219     const bool level1_depth_flag = encoder_.level1_depth_flag();
00220 
00221     for (unsigned f = 0; f < frame_count; ++f, pts += duration) {
00222         INFO("Writing base %d", f);
00223         const Image src = ExpandImage(src_file->read(f, pts), encoder_.enhancement_image_description());
00224         // Downsample and bit shifting depending base and enhancement bit depths
00225         const Image img = DownsampleImage(DownsampleImage(src, downsample_luma_, downsample_chroma_, scaling_mode_[LOQ_LEVEL_2],
00226                                                           level1_depth_flag ? 0 : encoder_.base_image_description().bit_depth()),
00227                                           downsample_luma_, downsample_chroma_, scaling_mode_[LOQ_LEVEL_1],
00228                                           level1_depth_flag ? encoder_.base_image_description().bit_depth() : 0);
00229         base_yuv->write(img);
00230     }
00231 
00232     // Run the base encoder yuv-file-> es-file and recon
00233     run_base_encoder(base_yuv->filename(), base_bin_filename, base_recon_filename, frame_count);
00234 
00235     // Open file
00236     unique_ptr<YUVReader> recon_file(CHECK(CreateYUVReader(base_recon_filename, encoder_.base_image_description(), fps_)));
00237 
00238     UniquePtrFile output_file(CHECK(fopen(format("%s", dst_filename.c_str()).c_str(), "wb")));
00239 
00240     ESFile es_file;
00241     CHECK(es_file.Open(base_bin_filename, es_file_type()));
00242 
00243     // Encode enhancement given src, base and base_recon
00244     clock_t EnhaClock1 = clock();
00245 
00246     encode(*src_file, *recon_file, output_file.get(), es_file, dst_filename_yuv, limit);
00247 
00248     clock_t EnhaClock2 = clock();
00249 
00250     INFO("**** Encode enhancement. delta. %16d secs", (EnhaClock2 - EnhaClock1) / CLOCKS_PER_SEC);
00251     // Clear up
00252     if (!parameters_["keep_base"].get<bool>(false)) {
00253         ::remove(base_yuv_filename.c_str());
00254         ::remove(base_bin_filename.c_str());
00255         ::remove(base_recon_filename.c_str());
00256     }
00257 }
00258 
00259 void FileEncoderImpl::encode_file_with_decoder(const string &src_filename, const string base_filename, const string &dst_filename,
00260                                                const string &dst_filename_yuv, unsigned limit) {
00261 
00262     // Initialize encoder to derive final dimensions
00263     unique_ptr<YUVReader> src_file(CHECK(CreateYUVReader(src_filename, encoder_.src_image_description(), fps_)));
00264     initialize_encoder(*src_file, limit);
00265 
00266     // Verify dimensions of base input
00267     unsigned base_width = 0, base_height = 0, base_depth = 0, chroma_format_idc;
00268     if (probe_es_file(base_filename, base_coding(), base_width, base_height, base_depth, chroma_format_idc)) {
00269         CHECK(base_width == encoder_.base_image_description().width());
00270         CHECK(base_height == encoder_.base_image_description().height());
00271         CHECK(base_depth == encoder_.base_image_description().bit_depth());
00272         CHECK(chroma_format_idc == (unsigned)encoder_.base_image_description().colourspace());
00273     } else {
00274         WARN("Cannot find dimension of base.");
00275     }
00276 
00277     // Generate base recon.
00278     string base_recon_filename = make_temporary_filename(
00279         format("_base_recon_%dx%d.yuv", encoder_.base_image_description().width(), encoder_.base_image_description().height()));
00280     INFO("Using temporary file for base recon: %s", base_recon_filename.c_str());
00281 
00282     INFO("-- Starting decoding process: %.3f", system_timestamp() / 1000000.0);
00283     run_base_decoder(base_filename, base_recon_filename);
00284 
00285     // Open file
00286     unique_ptr<YUVReader> recon_file(CHECK(CreateYUVReader(base_recon_filename, encoder_.base_image_description(), fps_)));
00287 
00288     UniquePtrFile output_file(CHECK(fopen(format("%s", dst_filename.c_str()).c_str(), "wb")));
00289 
00290     ESFile es_file;
00291     CHECK(es_file.Open(base_filename, es_file_type()));
00292 
00293     encode(*src_file, *recon_file, output_file.get(), es_file, dst_filename_yuv, limit);
00294 
00295     // Clear up
00296     if (!parameters_["keep_base"].get<bool>(false)) {
00297         ::remove(base_recon_filename.c_str());
00298     }
00299 }
00300 
00301 // Fetch next AU from an ES file - return true if not EOF
00302 //
00303 bool FileEncoderImpl::read_au(ESFile &es_file, ESFile::AccessUnit &au) {
00304     ESFile::Result rc = ESFile::EndOfFile;
00305 
00306     try {
00307         rc = es_file.NextAccessUnit(au);
00308     } catch (const runtime_error &) {
00309         rc = ESFile::NalParsingError;
00310     }
00311 
00312     return rc == ESFile::Success;
00313 }
00314 
00315 static BaseFrameType frame_type(BaseDecPictType::Enum pt) {
00316     switch (pt) {
00317     case BaseDecPictType::IDR:
00318         return BaseFrame_IDR;
00319     case BaseDecPictType::I:
00320         return BaseFrame_Intra;
00321     case BaseDecPictType::P:
00322         // return BaseFrame_Inter;
00323         return BaseFrame_Pred;
00324     case BaseDecPictType::B:
00325         // return BaseFrame_Inter;
00326         return BaseFrame_Bidi;
00327     case BaseDecPictType::BR:
00328         // return BaseFrame_Inter;
00329         return BaseFrame_Bidi;
00330     case BaseDecPictType::Unknown:
00331         return BaseFrame_Inter;
00332     default:
00333         CHECK(0);
00334         return BaseFrame_IDR;
00335     }
00336 }
