00338 void FileEncoderImpl::encode_file_with_base(const string &src_filename, const string base_filename,
00339                                             const string base_recon_filename, const string &dst_filename,
00340                                             const string &dst_filename_yuv, unsigned limit) {
00341     // Open files
00342     //
00343     unique_ptr<YUVReader> src_file(CHECK(CreateYUVReader(src_filename, encoder_.src_image_description(), fps_)));
00344     unique_ptr<YUVReader> recon_file(CHECK(CreateYUVReader(base_recon_filename, encoder_.base_image_description(), fps_)));
00345 
00346     initialize_encoder(*src_file, limit);
00347 
00348     // Verify dimensions of base input
00349     unsigned base_width = 0, base_height = 0, base_depth = 0, chroma_format_idc;
00350     if (probe_es_file(base_filename, base_coding(), base_width, base_height, base_depth, chroma_format_idc)) {
00351         CHECK(base_width == encoder_.base_image_description().width());
00352         CHECK(base_height == encoder_.base_image_description().height());
00353         CHECK(base_depth == encoder_.base_image_description().bit_depth());
00354         CHECK(chroma_format_idc == (unsigned)encoder_.base_image_description().colourspace());
00355     } else {
00356         WARN("Cannot find dimension of base.");
00357     }
00358 
00359     UniquePtrFile output_file(CHECK(fopen(format("%s", dst_filename.c_str()).c_str(), "wb")));
00360 
00361     ESFile es_file;
00362     CHECK(es_file.Open(base_filename, es_file_type()));
00363 
00364     encode(*src_file, *recon_file, output_file.get(), es_file, dst_filename_yuv, limit);
00365 }
