00367 template <typename T, typename... Args> std::unique_ptr<T> make_unique(Args &&...args) {
00368     return std::unique_ptr<T>(new T(std::forward<Args>(args)...));
00369 }
00370 
00371 void FileEncoderImpl::encode(const YUVReader &src_file, const YUVReader &recon_file, FILE *output_file, ESFile &es_file,
00372                              const string &dst_filename_yuv, unsigned limit) {
00373 
00374     // Queue of pending AUs, so that enhancment can be encoded in display order
00375     deque<ESFile::AccessUnit> pending;
00376 
00377     unsigned display_frame = 0;
00378     unsigned written_count = 0;
00379     bool end_of_es = false;
00380     encoder_.set_last_idr_frame_num(0);
00381     std::vector<std::unique_ptr<Image>> src;
00382 
00383     const unsigned num_frames = std::min(src_file.length(), limit);
00384     if (num_frames == 0)
00385         ERR("Frames cannot be read from source.");
00386 
00387     // Fill with initial frame
00388     src.push_back(make_unique<Image>(ExpandImage(src_file.read(0, 0), encoder_.enhancement_image_description())));
00389 
00390     while (written_count < limit && !end_of_es) {
00391 
00392         // Get next AU from base stream
00393         ESFile::AccessUnit au;
00394         if (read_au(es_file, au))
00395             pending.push_front(au);
00396         else
00397             end_of_es = true;
00398 
00399         // Advance 'enhancement_poc' past AUs that are present in queue, adding enhancement as needed
00400         bool keep_looking = false;
00401         do {
00402             keep_looking = false;
00403             for (auto &a : pending) {
00404 
00405                 // AVC POCs are increased by 2 XXX move to virtual fn
00406                 const unsigned enhance_poc = (es_file_type() == BaseDecoder::AVC) ? 2 * display_frame : display_frame;
00407 
00408                 if (a.m_poc == enhance_poc) {
00409                     if (display_frame != 0)
00410                         src.erase(src.begin());
00411                     if (src.size() < 2 && (display_frame + 1) < src_file.length()) {
00412                         src.push_back(make_unique<Image>(ExpandImage(src_file.read(display_frame + 1, display_frame + 1),
00413                                                                      encoder_.enhancement_image_description())));
00414                     }
00415 
00416                     const Image recon = recon_file.read(display_frame, display_frame);
00417 
00418                     const Image src_intermediate =
00419                         DownsampleImage(*src[0], downsample_luma_, downsample_chroma_, scaling_mode_[LOQ_LEVEL_2],
00420                                         encoder_.intermediate_image_description().bit_depth());
00421 
00422                     // Enhancement encoding
00423                     const bool is_idr = a.m_pictureType == BaseDecPictType::IDR;
00424                     Packet pss = encoder_.encode(src, src_intermediate, recon, frame_type(a.m_pictureType), is_idr, display_frame,
00425                                                  dst_filename_yuv);
00426 
00427                     goReportStructure.miTimeStamp = (int)a.m_poc;
00428                     goReportStructure.miPictureType = (int)a.m_pictureType;
00429                     goReportStructure.miBaseSize = (int)a.m_size;
00430                     if (!pss.empty())
00431                         goReportStructure.miEnhancementSize = add_enhancement(a, is_idr, pss);
00432                     goReportQueue.push(goReportStructure);
00433                     goPsnr.miBaseBytes += goReportStructure.miBaseSize;
00434                     goPsnr.miEnhancementBytes += goReportStructure.miEnhancementSize;
00435 
00436                     // clang-format off
00437                     fprintf(stdout, "ENC. [pts. %4d] [type %4d] [base %8d] [enha %8d] ",
00438                         goReportStructure.miTimeStamp, goReportStructure.miPictureType, goReportStructure.miBaseSize, goReportStructure.miEnhancementSize);
00439                     fflush(stdout);
00440                     fprintf(stdout, "[psnrY %8.4f] ", goPsnr.mfCurPsnr[0]);
00441                     if (encoder_.src_image_description().num_planes() > 1)
00442                         fprintf(stdout, "[psnrU %8.4f] [psnrV %8.4f] \n", (goPsnr.mfCurPsnr[1]), (goPsnr.mfCurPsnr[2]));
00443                     else
00444                         fprintf(stdout, "\n");
00445                     fflush(stdout);
00446                     fprintf(stdout, "[MD5Y %02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X] ", 
00447                         gaucMd5Digest[0][0],  gaucMd5Digest[0][1],  gaucMd5Digest[0][2],  gaucMd5Digest[0][3],  
00448                         gaucMd5Digest[0][4],  gaucMd5Digest[0][5],  gaucMd5Digest[0][6],  gaucMd5Digest[0][7],  
00449                         gaucMd5Digest[0][8],  gaucMd5Digest[0][9],  gaucMd5Digest[0][10], gaucMd5Digest[0][11], 
00450                         gaucMd5Digest[0][12], gaucMd5Digest[0][13], gaucMd5Digest[0][14], gaucMd5Digest[0][15]);
00451                     fflush(stdout);
00452                     if (encoder_.src_image_description().num_planes() > 1) {
00453                         fprintf(stdout, "[MD5U %02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X] ", 
00454                             gaucMd5Digest[1][0],  gaucMd5Digest[1][1],  gaucMd5Digest[1][2],  gaucMd5Digest[1][3],  
00455                             gaucMd5Digest[1][4],  gaucMd5Digest[1][5],  gaucMd5Digest[1][6],  gaucMd5Digest[1][7],  
00456                             gaucMd5Digest[1][8],  gaucMd5Digest[1][9],  gaucMd5Digest[1][10], gaucMd5Digest[1][11], 
00457                             gaucMd5Digest[1][12], gaucMd5Digest[1][13], gaucMd5Digest[1][14], gaucMd5Digest[1][15]);
00458                         fflush(stdout);
00459                         fprintf(stdout, "[MD5V %02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X] \n", 
00460                             gaucMd5Digest[2][0],  gaucMd5Digest[2][1],  gaucMd5Digest[2][2],  gaucMd5Digest[2][3],  
00461                             gaucMd5Digest[2][4],  gaucMd5Digest[2][5],  gaucMd5Digest[2][6],  gaucMd5Digest[2][7],  
00462                             gaucMd5Digest[2][8],  gaucMd5Digest[2][9],  gaucMd5Digest[2][10], gaucMd5Digest[2][11], 
00463                             gaucMd5Digest[2][12], gaucMd5Digest[2][13], gaucMd5Digest[2][14], gaucMd5Digest[2][15]);
00464                         fflush(stdout);
00465                     } else {
00466                         fprintf(stdout, "\n");
00467                         fflush(stdout);
00468                     }
00469                     // clang-format on
00470 
00471                     display_frame++;
00472                     keep_looking = true;
00473 
00474                     // INFO("base -- %4u %8u %4u", display_frame, pss.size(), a.m_pictureType);
00475                     break;
00476                 }
00477             }
00478         } while (keep_looking);
00479 
00480         // Consume AUs that have been enhanced from the back of queue and write to output stream
00481         const unsigned write_poc = (es_file_type() == BaseDecoder::AVC) ? 2 * display_frame : display_frame;
00482         while (!pending.empty() && (pending.back().m_poc < write_poc)) {
00483             for (const auto &n : pending.back().m_nalUnits) {
00484                 size_t sz = n.m_data.size();
00485                 // INFO("lvc  -- %4u %8u", written_count, sz);
00486                 CHECK(fwrite(n.m_data.data(), 1, sz, output_file) == sz);
00487             }
00488             pending.pop_back();
00489             ++written_count;
00490         }
00491     }
00492 
00493     if (written_count > 0) {
00494         int iFrames = written_count;
00495 
00496         float fAccMse[MAX_NUM_PLANES];
00497         float fPsnr[MAX_NUM_PLANES];
00498         for (unsigned plane = 0; plane < encoder_.src_image_description().num_planes(); plane++) {
00499             fAccMse[plane] = goPsnr.mfAccMse[plane] / iFrames;
00500             fPsnr[plane] = (float)(10.0f * log10((32767.0f * 32767.0f) / fAccMse[plane]));
00501         }
00502 
00503         REPORT("========= ========= ========= ========= ========= ========= ========= ========= ");
00504         if (encoder_.src_image_description().num_planes() > 1)
00505             REPORT("PSNR -- YUV %8.4f -- Y %8.4f U %8.4f V %8.4f", (6 * fPsnr[0] + fPsnr[1] + fPsnr[2]) / 8, fPsnr[0], fPsnr[1],
00506                    fPsnr[2]);
00507         else
00508             REPORT("PSNR -- Y %8.4f", fPsnr[0]);
00509         REPORT("========= ========= ========= ========= ========= ========= ========= ========= ");
00510         REPORT("BITS -- base %8d bps -- enha %8d bps ", (goPsnr.miBaseBytes * 8 * this->fps_) / iFrames,
00511                (goPsnr.miEnhancementBytes * 8 * this->fps_) / iFrames);
00512         REPORT("========= ========= ========= ========= ========= ========= ========= ========= ");
00513     }
00514     
00515 }
00516 
00517 // RBSP encapsualtion (0b00000000 0b00000000 0b000000xx -> 0b00000000 0b00000000 0b00000011 0b000000xx)
00518 //
00519 Packet FileEncoderImpl::rbsp_encapsulate(const Packet &src) const {
00520     PacketView in(src);
00521 
00522     vector<uint8_t> out;
00523 
00524     unsigned zeros = 0;
00525     for (unsigned int i = 0; i < in.size(); ++i) {
00526         uint8_t b = in.data()[i];
00527 
00528         if (zeros == 2 && (b & ~3) == 0) {
00529             out.push_back(0x03);
00530             zeros = 0;
00531         }
00532 
00533         if (b == 0)
00534             ++zeros;
00535         else
00536             zeros = 0;
00537 
00538         out.push_back(b);
00539     }
00540 
00541     out.push_back(0x80);
00542 
00543     return Packet::build().contents(out).finish();
00544 }
00545 
00546 // Make the SEI encapsulated payload data given enhancement data
00547 //
00548 Packet FileEncoderImpl::RegisteredSEI::sei_payload(const Packet &enhancement_data) {
00549     BitstreamPacker sei;
00550 
00551     // SEI Type: Registered
00552     sei.u(8, 0x04);
00553 
00554     // SEI Length
00555     unsigned l = enhancement_data.size() + 4;
00556     while (l >= 255) {
00557         sei.u(8, 255);
00558         l -= 255;
00559     }
00560     sei.u(8, l);
00561 
00562     // SEI code
00563     static const uint8_t sei_code[4] = {0xb4, 0x00, 0x50, 0x00};
00564     sei.bytes(sei_code, 4);
00565 
00566     // Enhancement part of payload
00567     sei.bytes(enhancement_data);
00568 
00569     return sei.finish();
00570 }
00571 
00572 Packet FileEncoderImpl::UnregisteredSEI::sei_payload(const Packet &enhancement_data) {
00573     BitstreamPacker sei;
00574 
00575     // SEI Type: Unregistered
00576     sei.u(8, 0x05);
00577 
00578     // SEI Length
00579     unsigned l = enhancement_data.size() + 16;
00580     while (l >= 255) {
00581         sei.u(8, 255);
00582         l -= 255;
00583     }
00584     sei.u(8, l);
00585 
00586     // UUID
00587     static const uint8_t uuid[16] = {0xa7, 0xc4, 0x6d, 0xed, 0x49, 0xd8, 0x38, 0xeb,
00588                                      0x9a, 0xad, 0x6d, 0xa6, 0x84, 0x97, 0xa7, 0x54};
00589     sei.bytes(uuid, 16);
00590 
00591     // Enhancement part of payload
00592     sei.bytes(enhancement_data);
00593 
00594     return sei.finish();
00595 }
00596 
00597 // Make the NAL encapsulated payload data given enhancement data
00598 //
00599 Packet FileEncoderImpl::nal_payload(const Packet &enhancement_data) const {
00600     BitstreamPacker p;
00601 
00602     // Enhancement part of payload
00603     p.bytes(enhancement_data);
00604 
00605     return p.finish();
00606 }
00607 
00608 // Build  a standard LCEV NALU
00609 //
00610 ESFile::NalUnit FileEncoderImpl::build_nalu(const bool is_idr, const Packet &payload) const {
00611     // nal_marker, forbidden_zero_bit, forbidden_one_bit, nal_unit_type=28/29, reserved_flag
00612     const NalUnitType nal_type = is_idr ? NalUnitType::LCEVC_IDR : NalUnitType::LCEVC_NON_IDR;
00613     const uint8_t nalu_header_lcevc[5] = {0x00, 0x00, 0x01, (uint8_t)(is_idr ? 0x7b : 0x79), 0xff};
00614     ESFile::NalUnit nal_unit = {(uint32_t)nal_type, DataBuffer(nalu_header_lcevc, nalu_header_lcevc + sizeof(nalu_header_lcevc))};
00615 
00616     const Packet rbsp = rbsp_encapsulate(nal_payload(payload));
00617     const PacketView v(rbsp);
00618     nal_unit.m_data.insert(nal_unit.m_data.end(), v.data(), v.data() + v.size());
00619 
00620     return nal_unit;
00621 }
00622 
00623 // Figure out IntraPeriod for base layer
00624 //
00625 unsigned FileEncoderImpl::intra_period() const {
00626     // Check for explicit set
00627     if (!parameters_["intra_period"].empty())
00628         return parameters_["intra_period"].get<unsigned>();
00629 
00630     // .. otherwise derive from frame rate
00631     switch (fps_) {
00632     case 30:
00633         return 32;
00634     case 50:
00635         return 48;
00636     case 60:
00637         return 64;
00638 
00639     default:
00640         INFO("Unrecognised frame rate: %u", fps_);
00641         return 64;
00642     }
00643 }
00644 
00645 // Initialize Encoder configuration to figure out final dimensions (after possible conformance window)
00646 //
00647 void FileEncoderImpl::initialize_encoder(const YUVReader &src_file, unsigned limit) {
00648     std::vector<std::unique_ptr<Image>> src;
00649     const unsigned num_frames = std::min(src_file.length(), limit);
00650     if (num_frames == 0)
00651         ERR("Frames cannot be read from source.");
00652 
00653     // Fill vector with first 5 frames
00654     for (unsigned n = 0; n < std::min(5u, num_frames); n++)
00655         src.push_back(make_unique<Image>(ExpandImage(src_file.read(n, n), encoder_.enhancement_image_description())));
00656     encoder_.initialise_config(parameters_, src);
00657 }
