00660 //
00661 class FileEncoderImplAVC : public FileEncoderImpl {
00662 public:
00663     FileEncoderImplAVC(const ImageDescription &image_description, unsigned fps, const Parameters &parameters)
00664         : FileEncoderImpl(image_description, fps, parameters) {}
00665 
00666     BaseDecoder::Codec es_file_type() const override { return BaseDecoder::AVC; };
00667     BaseCoding base_coding() const override { return BaseCoding_AVC; }
00668 
00669     bool run_base_encoder(const string &yuv_file, const string &es_file, const string &recon_file,
00670                           unsigned frame_count) const override {
00671         const string prog = get_program_directory("external_codecs/JM/lencod");
00672         const string default_cfg = get_program_directory("external_codecs/JM/encoder.cfg");
00673         const string cfg = get_program_directory("external_codecs/JM/encoder_randomaccess.cfg");
00674 
00675         const unsigned qp_islice = encoder_.base_qp();
00676         const unsigned qp_pslice = qp_islice + 1;
00677         const unsigned qp_bslice = qp_islice + 1;
00678 
00679         string cmd_line =
00680             format("%s -d %s -f %s -p InputFile=%s -p OutputFile=%s -p ReconFile=%s "
00681                    "-p SourceWidth=%u -p SourceHeight=%u "
00682                    "-p SourceBitDepthLuma=%u -p SourceBitDepthChroma=%u -p OutputBitDepthLuma=%u -p OutputBitDepthChroma=%u "
00683                    "-p FrameRate=%u -p YUVFormat=%u "
00684                    "-p QPISlice=%u -p QPPSlice=%u -p QPBSlice=%u -p IntraPeriod=%u -p FramesToBeEncoded=%u",
00685                    prog.c_str(), default_cfg.c_str(), cfg.c_str(), yuv_file.c_str(), es_file.c_str(), recon_file.c_str(),
00686                    encoder_.base_image_description().width(), encoder_.base_image_description().height(),
00687                    encoder_.base_image_description().bit_depth(), encoder_.base_image_description().bit_depth(),
00688                    encoder_.base_image_description().bit_depth(), encoder_.base_image_description().bit_depth(), fps_,
00689                    (unsigned)encoder_.base_image_description().colourspace(), qp_islice, qp_pslice, qp_bslice, intra_period(),
00690                    frame_count);
00691 
00692         if (encoder_.base_image_description().colourspace() == Colourspace_YUV444)
00693             cmd_line.append(" -p WeightedPrediction=0 -p WeightedBiprediction=0 -p ProfileIDC=244");
00694         else if (encoder_.base_image_description().colourspace() == Colourspace_YUV422)
00695             cmd_line.append(" -p ProfileIDC=122");
00696 
00697         INFO("Running: %s", cmd_line.c_str());
00698         return system(cmd_line.c_str()) == 0;
00699     }
00700 
00701     // Insert enhancement data
00702     //
00703     int add_enhancement(ESFile::AccessUnit &au, bool is_idr, const Packet &payload) override {
00704         ESFile::NalUnit nal_unit;
00705 
00706         if (encapsulation_ == Encapsulation_None || encapsulation_ == Encapsulation_NAL) {
00707             // Use LCEVC Standard NALU
00708             nal_unit = build_nalu(is_idr, payload);
00709         } else if (encapsulation_ == Encapsulation_SEI_Registered) {
00710             // Encapsulate LCEVC Data into a NAL unit
00711             ESFile::NalUnit nal_unit_lcevc = build_nalu(is_idr, payload);
00712             Packet payload_lcevc = Packet::build().contents(nal_unit_lcevc.m_data).finish();
00713 
00714             // Regsitered SEI Encapsulation of LCEVC NAL unit
00715             // nal_marker, forbidden_zero_bit, nal_unit_type=6, reserved_flag
00716             static const uint8_t nalu_header[4] = {0x00, 0x00, 0x01, 0x06};
00717             nal_unit = {6, DataBuffer(nalu_header, nalu_header + sizeof(nalu_header))};
00718 
00719             Packet rbsp = rbsp_encapsulate(RegisteredSEI::sei_payload(payload_lcevc));
00720             const PacketView v(rbsp);
00721             nal_unit.m_data.insert(nal_unit.m_data.end(), v.data(), v.data() + v.size());
00722         } else if (encapsulation_ == Encapsulation_SEI_Unregistered) {
00723             // Ungreistered SEI Encapsulation
00724             // nal_marker, forbidden_zero_bit, nal_unit_type=6, reserved_flag
00725             static const uint8_t nalu_header[4] = {0x00, 0x00, 0x01, 0x06};
00726             nal_unit = {6, DataBuffer(nalu_header, nalu_header + sizeof(nalu_header))};
00727 
00728             Packet rbsp = rbsp_encapsulate(UnregisteredSEI::sei_payload(payload));
00729             const PacketView v(rbsp);
00730             nal_unit.m_data.insert(nal_unit.m_data.end(), v.data(), v.data() + v.size());
00731         } else {
00732             CHECK(0);
00733         }
00734 
00735         // Insert after - after AUD and PPS/SPS
00736         unsigned offset = 0;
00737         for (offset = 0; offset < au.m_nalUnits.size(); ++offset) {
00738             if (au.m_nalUnits[offset].m_type < 7 || au.m_nalUnits[offset].m_type > 9)
00739                 break;
00740         }
00741 
00742         au.m_nalUnits.insert(au.m_nalUnits.begin() + offset, nal_unit);
00743         return (int)(nal_unit.m_data.size());
00744     }
00745 
00746     bool run_base_decoder(const string &input, const string &output) override {
00747         string p = get_program_directory("external_codecs/JM/ldecod");
00748 
00749         INFO("Using base decoder %s", p.c_str());
00750 
00751         return system(format("%s -p InputFile=%s -p OutputFile=%s "
00752                              "-p WriteUV=0",
00753                              p.c_str(), input.c_str(), output.c_str())
00754                           .c_str()) == 0;
00755     }
00756 };
