00987 public:
00988     FileEncoderImplVVC(const ImageDescription &image_description, unsigned fps, const Parameters &parameters)
00989         : FileEncoderImpl(image_description, fps, parameters) {}
00990 
00991     BaseDecoder::Codec es_file_type() const override { return BaseDecoder::VVC; };
00992     BaseCoding base_coding() const override { return BaseCoding_VVC; }
00993 
00994     bool run_base_encoder(const string &yuv_file, const string &es_file, const string &recon_file,
00995                           unsigned frame_count) const override {
00996         const string prog = get_program_directory("external_codecs/VTM/EncoderApp");
00997         const string cfg = get_program_directory("external_codecs/VTM/vtm_encoder_randomaccess.cfg");
00998 
00999         const unsigned qp = encoder_.base_qp();
01000         unsigned chroma_format;
01001         switch (encoder_.base_image_description().colourspace()) {
01002         case Colourspace_Y:
01003             chroma_format = 400;
01004             break;
01005         case Colourspace_YUV420:
01006             chroma_format = 420;
01007             break;
01008         case Colourspace_YUV422:
01009             chroma_format = 422;
01010             break;
01011         case Colourspace_YUV444:
01012             chroma_format = 444;
01013             break;
01014         default:
01015             ERR("Not a colour space");
01016         }
01017 
01018         unsigned intra_period_vvc = intra_period();
01019         // since VTM 11, intra period must be multiple of 32 gop period
01020         if ((intra_period_vvc % 32) != 0)
01021             intra_period_vvc = round(intra_period_vvc / 32) * 32;
01022         if (intra_period_vvc < 32)
01023             intra_period_vvc = 32;
01024 
01025         string cmd_line =
01026             format("%s -c %s --InputFile=%s ---BitstreamFile=%s --ReconFile=%s "
01027                    "--SourceWidth=%d --SourceHeight=%d --InputBitDepth=%d --OutputBitDepth=%d --InternalBitDepth=%d --FrameRate=%d "
01028                    "--QP=%d --IntraPeriod=%d --FramesToBeEncoded=%d --ConformanceWindowMode=1 --InputChromaFormat=%u",
01029                    prog.c_str(), cfg.c_str(), yuv_file.c_str(), es_file.c_str(), recon_file.c_str(),
01030                    encoder_.base_image_description().width(), encoder_.base_image_description().height(),
01031                    encoder_.base_image_description().bit_depth(), encoder_.base_image_description().bit_depth(),
01032                    encoder_.base_image_description().bit_depth(), fps_, qp, intra_period_vvc, frame_count, chroma_format);
01033 
01034         INFO("Running: %s", cmd_line.c_str());
01035         return system(cmd_line.c_str()) == 0;
01036     }
01037 
01038     // Insert enhancement data NALU
01039     //
01040     int add_enhancement(ESFile::AccessUnit &au, bool is_idr, const Packet &payload) override {
01041         ESFile::NalUnit nal_unit;
01042 
01043         if (encapsulation_ == Encapsulation_None || encapsulation_ == Encapsulation_NAL) {
01044             // Use LCEVC Standard NALU
01045             nal_unit = build_nalu(is_idr, payload);
01046         } else if (encapsulation_ == Encapsulation_SEI_Registered) {
01047             // Encapsulate LCEVC Data into a NAL unit
01048             ESFile::NalUnit nal_unit_lcevc = build_nalu(is_idr, payload);
01049             Packet payload_lcevc = Packet::build().contents(nal_unit_lcevc.m_data).finish();
01050 
01051             // Regsitered SEI Encapsulation of LCEVC NAL unit
01052             const uint8_t nalu_header[5] = {0x00, 0x00, 0x01, 0x00,
01053                                             static_cast<uint8_t>(0xb8 | (au.m_temporalId + 1))}; // nal_unit_type=23 (SEI)
01054             nal_unit = {23, DataBuffer(nalu_header, nalu_header + sizeof(nalu_header))};
01055 
01056             Packet rbsp = rbsp_encapsulate(RegisteredSEI::sei_payload(payload_lcevc));
01057             const PacketView v(rbsp);
01058             nal_unit.m_data.insert(nal_unit.m_data.end(), v.data(), v.data() + v.size());
01059         } else if (encapsulation_ == Encapsulation_SEI_Unregistered) {
01060             // Unregistered SEI Encapsulation
01061             const uint8_t nalu_header[5] = {0x00, 0x00, 0x01, 0x00,
01062                                             static_cast<uint8_t>(0xb8 | (au.m_temporalId + 1))}; // nal_unit_type=23 (SEI)
01063             nal_unit = {23, DataBuffer(nalu_header, nalu_header + sizeof(nalu_header))};
01064 
01065             Packet rbsp = rbsp_encapsulate(UnregisteredSEI::sei_payload(payload));
01066             const PacketView v(rbsp);
01067             nal_unit.m_data.insert(nal_unit.m_data.end(), v.data(), v.data() + v.size());
01068         } else {
01069             CHECK(0);
01070         }
01071 
01072         unsigned offset = 0;
01073         for (offset = 0; offset < au.m_nalUnits.size(); ++offset) {
01074             if (au.m_nalUnits[offset].m_type < 12)
01075                 break;
01076         }
01077 
01078         au.m_nalUnits.insert(au.m_nalUnits.begin() + offset, nal_unit);
01079         return (int)(nal_unit.m_data.size());
01080     }
01081 
01082     bool run_base_decoder(const string &input, const string &output) override {
01083         string p = get_program_directory("external_codecs/VTM/DecoderApp");
01084 
01085         INFO("Using base decoder %s", p.c_str());
01086 
01087         return system(format("\"%s\" -d %u -b %s -o %s", p.c_str(), encoder_.base_image_description().bit_depth(), input.c_str(),
01088                              output.c_str())
01089                           .c_str()) == 0;
01090     }
01091 };
