01094 //
01095 class FileEncoderImplEVC : public FileEncoderImpl {
01096 public:
01097     FileEncoderImplEVC(const ImageDescription &image_description, unsigned fps, const Parameters &parameters)
01098         : FileEncoderImpl(image_description, fps, parameters) {}
01099 
01100     BaseDecoder::Codec es_file_type() const override { return BaseDecoder::EVC; };
01101     BaseCoding base_coding() const override { return BaseCoding_EVC; }
01102 
01103     bool run_base_encoder(const string &yuv_file, const string &es_file, const string &recon_file,
01104                           unsigned frame_count) const override {
01105         if (encoder_.base_image_description().colourspace() != Colourspace_YUV420)
01106             ERR("Only encodings with a 4:2:0 colourspace are supported by the current version of ETM.");
01107         const string prog = get_program_directory("external_codecs/ETM/evca_encoder");
01108         const string cfg = get_program_directory("external_codecs/ETM/etm_encoder_randomaccess_main.cfg");
01109 
01110         const unsigned qp = encoder_.base_qp();
01111 
01112         string cmd_line = format("%s --config %s --input %s --output %s --recon %s "
01113                                  "--width %d --height %d --input_bit_depth %d --output_bit_depth %d --hz %d "
01114                                  "--op_qp %d --iperiod %d --frames %d",
01115                                  prog.c_str(), cfg.c_str(), yuv_file.c_str(), es_file.c_str(), recon_file.c_str(),
01116                                  encoder_.base_image_description().width(), encoder_.base_image_description().height(),
01117                                  encoder_.base_image_description().bit_depth(), encoder_.base_image_description().bit_depth(), fps_,
01118                                  qp, intra_period(), frame_count);
01119 
01120         INFO("Running: %s", cmd_line.c_str());
01121         return system(cmd_line.c_str()) == 0;
01122     }
01123 
01124     // Insert enhancement data NALU
01125     //
01126     int add_enhancement(ESFile::AccessUnit &au, bool is_idr, const Packet &payload) override {
01127         ESFile::NalUnit nal_unit;
01128 
01129         if (encapsulation_ == Encapsulation_None) {
01130             // No encapsulation - use LCEVC Standard NALU
01131             nal_unit = build_nalu(is_idr, payload);
01132         } else if (encapsulation_ == Encapsulation_SEI_Registered) {
01133             // Encapsulate LCEVC Data into a NAL unit
01134 
01135             ESFile::NalUnit nal_unit_lcevc;
01136             static const uint8_t nalu_header_lcevc[5] = {0x00, 0x00, 0x01, 0x79, 0xff};
01137             nal_unit_lcevc = {29, DataBuffer(nalu_header_lcevc, nalu_header_lcevc + sizeof(nalu_header_lcevc))};
01138 
01139             Packet rbsp_lcevc = rbsp_encapsulate(nal_payload(payload));
01140             const PacketView v_lcevc(rbsp_lcevc);
01141             nal_unit_lcevc.m_data.insert(nal_unit_lcevc.m_data.end(), v_lcevc.data(), v_lcevc.data() + v_lcevc.size());
01142 
01143             Packet payload_lcevc = Packet::build().contents(nal_unit_lcevc.m_data).finish();
01144 
01145             // Regsitered SEI Encapsulation of LCEVC NAL unit, nal_unit_type_plus1=29 (28 -> SEI)
01146             const uint8_t nalu_header[2] = {static_cast<uint8_t>(0x3a | (au.m_temporalId >> 2)),
01147                                             static_cast<uint8_t>((au.m_temporalId << 6) & 255)};
01148 
01149             Packet p = RegisteredSEI::sei_payload(payload_lcevc);
01150             const PacketView v(p);
01151             uint32_t payload_length = v.size() + sizeof(nalu_header);
01152             nal_unit = {27, DataBuffer((uint8_t *)&payload_length, (uint8_t *)&payload_length + sizeof(payload_length))};
01153 
01154             nal_unit.m_data.insert(nal_unit.m_data.end(), nalu_header, nalu_header + sizeof(nalu_header));
01155 
01156             nal_unit.m_data.insert(nal_unit.m_data.end(), v.data(), v.data() + v.size());
01157         } else if (encapsulation_ == Encapsulation_SEI_Unregistered) {
01158             // Unregistered SEI Encapsulation, nal_unit_type_plus1=29 (28 -> SEI)
01159             const uint8_t nalu_header[2] = {static_cast<uint8_t>(0x3a | (au.m_temporalId >> 2)),
01160                                             static_cast<uint8_t>((au.m_temporalId << 6) & 255)};
01161 
01162             Packet p = UnregisteredSEI::sei_payload(payload);
01163             const PacketView v(p);
01164             uint32_t payload_length = v.size() + sizeof(nalu_header);
01165             nal_unit = {27, DataBuffer((uint8_t *)&payload_length, (uint8_t *)&payload_length + sizeof(payload_length))};
01166 
01167             nal_unit.m_data.insert(nal_unit.m_data.end(), nalu_header, nalu_header + sizeof(nalu_header));
01168 
01169             nal_unit.m_data.insert(nal_unit.m_data.end(), v.data(), v.data() + v.size());
01170         } else if (encapsulation_ == Encapsulation_NAL) {
01171             // NAL Encapsulation, nal_unit_type_plus1=30 (29 -> Reserved)
01172             const uint8_t nalu_header[2] = {static_cast<uint8_t>(0x3c | (au.m_temporalId >> 2)),
01173                                             static_cast<uint8_t>((au.m_temporalId << 6) & 255)};
01174 
01175             Packet p = nal_payload(payload);
01176             const PacketView v(p);
01177 
01178             uint32_t payload_length = v.size() + sizeof(nalu_header);
01179             nal_unit = {28, DataBuffer((uint8_t *)&payload_length, (uint8_t *)&payload_length + sizeof(payload_length))};
01180 
01181             // NAL Encapsulation
01182             nal_unit.m_data.insert(nal_unit.m_data.end(), nalu_header, nalu_header + sizeof(nalu_header));
01183 
01184             nal_unit.m_data.insert(nal_unit.m_data.end(), v.data(), v.data() + v.size());
01185         } else {
01186             CHECK(0);
01187         }
01188 
01189         unsigned offset = 0;
01190         for (offset = 0; offset < au.m_nalUnits.size(); ++offset) {
01191             if (au.m_nalUnits[offset].m_type < 24 || au.m_nalUnits[offset].m_type > 26)
01192                 break;
01193         }
01194 
01195         au.m_nalUnits.insert(au.m_nalUnits.begin() + offset, nal_unit);
01196         return (int)(nal_unit.m_data.size());
01197     }
01198 
01199     bool run_base_decoder(const string &input, const string &output) override {
01200         string p = get_program_directory("external_codecs/ETM/evca_decoder");
01201 
01202         INFO("Using base decoder %s", p.c_str());
01203         return system(format("\"%s\" --output_bit_depth %d --input %s --output %s", p.c_str(),
01204                              encoder_.base_image_description().bit_depth(), input.c_str(), output.c_str())
01205                           .c_str()) == 0;
01206     }
01207 };
