01209 // Downsample input according to current settings and write to output file
01210 //
01211 void FileEncoderImpl::downsample_file(const string &input_file, const string &output_file, unsigned limit) {
01212     auto input = CHECK(CreateYUVReader(input_file, encoder_.src_image_description(), fps_));
01213     auto output = CHECK(CreateYUVWriter(output_file, encoder_.base_image_description(), true));
01214 
01215     const unsigned frame_count = min(input->length(), limit);
01216     INFO("Downsampling %d frames", frame_count);
01217 
01218     for (unsigned f = 0; f < frame_count; ++f) {
01219         INFO("  Writing downsampled %d", f);
01220         const Image src = input->read(f, f);
01221         const Image img = DownsampleImage(DownsampleImage(src, downsample_luma_, downsample_chroma_, scaling_mode_[LOQ_LEVEL_2]),
01222                                           downsample_luma_, downsample_chroma_, scaling_mode_[LOQ_LEVEL_1]);
01223         output->write(img);
01224     }
01225 }
01226 
01227 // Upsample input according to current settings and write to output file
01228 //
01229 void FileEncoderImpl::upsample_file(const string &input_file, const string &output_file, unsigned limit) {
01230     auto input = CHECK(CreateYUVReader(input_file, encoder_.base_image_description(), fps_));
01231     auto output = CHECK(CreateYUVWriter(output_file, encoder_.src_image_description(), true));
01232 
01233     const unsigned frame_count = min(input->length(), limit);
01234     INFO("Upsampling %d frames", frame_count);
01235 
01236     for (unsigned f = 0; f < frame_count; ++f) {
01237         INFO("  Writing upsampled %d", f);
01238         const Image src = input->read(f, f);
01239         const Image img = UpsampleImage(UpsampleImage(src, upsample_, upsampling_coefficients_, scaling_mode_[LOQ_LEVEL_2]),
01240                                         upsample_, upsampling_coefficients_, scaling_mode_[LOQ_LEVEL_1]);
01241         output->write(img);
01242     }
01243 }
01244 
01245 // Factory function
01246 //
01247 unique_ptr<FileEncoder> CreateFileEncoder(BaseCoding base_encoder, const ImageDescription &image_description, unsigned fps,
01248                                           const Parameters &parameters) {
01249     try {
01250         if (base_encoder == BaseCoding_AVC)
01251             return unique_ptr<FileEncoder>(new FileEncoderImplAVC(image_description, fps, parameters));
01252         else if (base_encoder == BaseCoding_HEVC)
01253             return unique_ptr<FileEncoder>(new FileEncoderImplHEVC(image_description, fps, parameters));
01254         else if (base_encoder == BaseCoding_VVC)
01255             return unique_ptr<FileEncoder>(new FileEncoderImplVVC(image_description, fps, parameters));
01256         else if (base_encoder == BaseCoding_EVC)
01257             return unique_ptr<FileEncoder>(new FileEncoderImplEVC(image_description, fps, parameters));
01258         else if (base_encoder == BaseCoding_X265)
01259             return unique_ptr<FileEncoder>(new FileEncoderImplX265(image_description, fps, parameters));
01260         else
01261             ERR("Unknown base codec");
01262     } catch (string e) {
01263         ERR("CreateFileEncoderImpl: Caught: %s\n", e.c_str());
01264     }
01265 
01266     return nullptr;
01267 }
